
module \cell
    #(
        parameter MODE = 8'h00
    )
    (
    input wire [0:0] I_a
    , input wire [0:0] I_b
    , input wire [0:0] I_c
    , input wire [0:0] I_d
    , output reg [0:0] O_a
    , output reg [0:0] O_b
    , output reg [0:0] O_c
        // prog_data[ 0 +:  8] pea mode select
    );

   localparam PEA_MODE = 0;
   localparam PEA_MODE_WIDTH = 8;
   
   reg x1, y1, x2, y2, x3, y3;
   
   wire [PEA_MODE_WIDTH-1:0] pea_mode;
   
   assign pea_mode = MODE[PEA_MODE+:PEA_MODE_WIDTH];

   // -- Input muxes ---------------------------------

   // pea_mode[7:6] == 2'b00: connection 1
   // pea_mode[7:6] == 2'b01: connection 2
   // pea_mode[7:6] == 2'b11: connection 3   
   
   always @* begin
      x1 = I_a;
      y1 = (pea_mode[6] == 1'b0) ? O_b : I_b;
      x2 = (pea_mode[6] == 1'b0) ? I_b : O_a;
      y2 = (pea_mode[7] == 1'b0) ? I_c : O_c;
      x3 = (pea_mode[7] == 1'b0) ? O_b : I_c;
      y3 = I_d;
   end

   // -- Outputs -------------------------------------
   always @* begin
	 O_a = (x1 & (y1 ^ pea_mode[0])) ^ pea_mode[1];
	 O_b = (x2 & (y2 ^ pea_mode[2])) ^ pea_mode[3];
	 O_c = (x3 & (y3 ^ pea_mode[4])) ^ pea_mode[5];	 	 
   end

endmodule

